require __DIR__.'/../api/life/store.php';require __DIR__.'/../api/life/ai.php';
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$db->exec(file_get_contents(__DIR__.'/../api/life/schema.sql'));$store=new LifeStore($db);$store->initialize('disposable-history-test');$n=0;function hist($ok){global $n;if(!$ok)throw new Exception('History check '.$n.' failed');$n++;}
$r=$store->read();$list=$r['state']['lists'][0]['id'];$blocked=array_values(array_filter($r['state']['lists'],fn($l)=>$l['name']==='Blocked'))[0]['id'];hist($store->history->page()['entries']===[]);
$r=$store->mutate($r['version'],'task.save',['title'=>'Write first draft','listId'=>$list]);$id=$r['state']['tasks'][0]['id'];hist(count($store->history->page()['entries'])===0);
$r=$store->mutate($r['version'],'task.move',['id'=>$id,'listId'=>$blocked]);hist(count($store->history->page()['entries'])===1);hist($store->history->page()['entries'][0]['status']==='blocked');
$r=$store->mutate($r['version'],'task.save',array_replace($r['state']['tasks'][0],['title'=>'Write final draft']));hist(count($store->history->page()['entries'])===1);hist($store->history->page()['entries'][0]['task']['title']==='Write first draft');
$r=$store->mutate($r['version'],'task.complete',['id'=>$id,'done'=>true]);hist(count($store->history->page(['status'=>'done'])['entries'])===1);$r=$store->mutate($r['version'],'task.complete',['id'=>$id,'done'=>false]);hist(count($store->history->page(['status'=>'done'])['entries'])===1);
$r=$store->mutate($r['version'],'task.archive',['id'=>$id]);hist(count($store->history->page(['status'=>'archived'])['entries'])===1);$saved=$store->history->export();$r=$store->mutate($r['version'],'task.restore',['id'=>$id,'listId'=>$list]);hist($store->history->export()===$saved);
