// Rollbacks include journal writes; Undo preserves earlier immutable events.
$ai=new LifeAI($store,[],fn()=>[]);$text='Move Write final draft to Blocked';$plan=['authorization'=>$text,'actions'=>[['operation'=>'task.move','arguments'=>json_encode(['id'=>$id,'listId'=>$blocked])],['operation'=>'task.move','arguments'=>json_encode(['id'=>'missing','listId'=>$blocked])]]];try{LifeCommands::execute($store,$ai,$ai->read()['version'],$r['version'],$text,$plan,'history-rollback');hist(false);}catch(LifeError $e){hist($store->history->export()===$saved);}
$plan['actions']=[$plan['actions'][0]];$result=LifeCommands::execute($store,$ai,$ai->read()['version'],$store->read()['version'],$text,$plan,'history-undo');$events=$store->history->export();LifeCommands::undo($store,$ai,$result['version'],$result['receipt']['id']);hist($store->history->export()===$events);
// Account journals are isolated even if the mutable planner is replaced.
