$r=$store->mutate($store->read()['version'],'goal.save',['title'=>'Finish Résumé 100%','notes'=>'My next chapter','type'=>'adhoc','completed'=>true]);$gid=end($r['state']['goals'])['id'];
$goal=$store->history->page(['search'=>'résumé'])['entries'];hist(count($goal)===1);hist($goal[0]['kind']==='goal');hist(count($store->history->page(['search'=>'100%'])['entries'])===1);hist(count($store->history->page(['search'=>'next chapter'])['entries'])===1);
$r=$store->mutate($r['version'],'history.restore',['id'=>$goal[0]['id'],'type'=>'month','period'=>'2026-11']);$g=end($r['state']['goals']);hist(!$g['completed']&&!$g['archived']);hist($g['period']==='2026-11');hist(count($store->history->page(['search'=>'résumé'])['entries'])===1);
// Reopening is explicit, preserves newer edits and never duplicates a current task.
