$r=$store->mutate($r['version'],'task.save',array_replace($task,['title'=>'Newer title','notes'=>'Keep these newer notes']));$beforeCount=count($r['state']['tasks']);
$r=$store->mutate($r['version'],'history.restore',['id'=>$source['id'],'listId'=>$list]);$task=array_values(array_filter($r['state']['tasks'],fn($t)=>$t['id']===$tid))[0];hist($task['title']==='Newer title'&&$task['notes']==='Keep these newer notes');hist($task['listId']===$list&&empty($task['completedAt'])&&$task['blocker']==='');hist(count($r['state']['tasks'])===$beforeCount);
$done=array_values(array_filter($r['state']['lists'],fn($l)=>$l['isDone']))[0]['id'];
foreach([['listId'=>'missing'],['listId'=>$done]] as $args){$v=$store->read()['version'];try{$store->mutate($v,'history.restore',['id'=>$source['id']]+$args);hist(false);}catch(LifeError $e){hist($store->read()['version']===$v);}}
// Owner-only access, confirmation, version conflicts and tenant checks.
