try{$other->mutate($other->read()['version'],'history.delete',['id'=>$source['id'],'confirmed'=>true]);hist(false);}catch(LifeError $e){hist($e->status===404);}
$v=$store->read()['version'];try{$store->mutate($v-1,'history.delete',['id'=>$source['id'],'confirmed'=>true]);hist(false);}catch(LifeError $e){hist($e->status===409);}
$r=$store->mutate($v,'history.delete',['id'=>$source['id'],'confirmed'=>true]);hist($store->history->page(['search'=>'Blocked history 100'])['entries']===[]);hist(count($r['state']['tasks'])===$beforeCount);try{$store->history->get($source['id']);hist(false);}catch(LifeError $e){hist($e->status===404);}
// Deleted history never comes back after reseeding or constructing a new store.
