try{$store->mutate($r['version'],'history.restore',['id'=>$goal[0]['id'],'type'=>'adhoc']);hist(false);}catch(LifeError $e){hist($e->status===404);}
// Archived goals are included and reopen unfinished; invalid periods are rejected atomically.
$r=$store->mutate($store->read()['version'],'goal.archive',['id'=>$gid]);$gh=$store->history->page(['search'=>'résumé','status'=>'archived'])['entries'][0];hist($gh['kind']==='goal');
try{$store->mutate($r['version'],'history.restore',['id'=>$gh['id'],'type'=>'month','period'=>'2026-99']);hist(false);}catch(LifeError $e){hist($store->read()['version']===$r['version']);}
$r=$store->mutate($r['version'],'history.restore',['id'=>$gh['id'],'type'=>'adhoc','period'=>'']);hist(!end($r['state']['goals'])['archived']);
// A deleted last entry is not reseeded even when its live task remains completed.
$freshDb=new PDO('sqlite::memory:');$freshDb->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$freshDb->exec(file_get_contents(__DIR__.'/../api/life/schema.sql'));$fresh=new LifeStore($freshDb);$fresh->initialize('another-disposable-history-test');$fr=$fresh->read();$fl=$fr['state']['lists'][0]['id'];$fr=$fresh->mutate($fr['version'],'task.save',['title'=>'Only completed record','listId'=>$fl]);$fid=$fr['state']['tasks'][0]['id'];$fr=$fresh->mutate($fr['version'],'task.complete',['id'=>$fid,'done'=>true]);$fh=$fresh->history->page()['entries'][0];
$fr=$fresh->mutate($fr['version'],'history.delete',['id'=>$fh['id'],'confirmed'=>true]);hist((new LifeStore($freshDb))->history->page()['entries']===[]);hist(!empty($fr['state']['tasks'][0]['completedAt']));
// History can recover a record absent from the mutable planner without inventing a new identity.
$fr=$fresh->mutate($fr['version'],'task.archive',['id'=>$fid]);$fh=$fresh->history->page()['entries'][0];$empty=$fr['state'];$empty['tasks']=[];$freshDb->prepare('UPDATE life_board SET state=? WHERE id=1')->execute([json_encode($empty)]);$fr=$fresh->mutate($fr['version'],'history.restore',['id'=>$fh['id'],'listId'=>$fl]);hist(count($fr['state']['tasks'])===1);hist($fr['state']['tasks'][0]['id']===$fid);hist(!$fr['state']['tasks'][0]['archived']&&empty($fr['state']['tasks'][0]['completedAt']));
